// 답변을 Discord에서 읽히는 모양으로 정규화한다. 내용은 건드리지 않고 배치와 라벨만 손본다.
//
// [왜 필요한가]
// 형식 규칙(첫 줄 핵심 문장, `- **용어**: 설명` 불릿)은 프롬프트로 "부탁"한 것이라
// gemma3:4b가 temperature 0.4에서 종종 통째로 무시한다. 실측 4건 중 2건이 그랬다.
//   실행 2106 — 658자를 개행 0개로 뱉어 한 문단이 됐다
//   실행 2122 — 리드 문장 없이 라벨 없는 맨 문장 불릿 17개
//   실행 2124 — 같은 모양으로 11개
// 잘 나온 답변(2120/2121)과 비교하면 차이는 딱 둘이다: 리드 문장이 있느냐, 불릿에
// 굵은 라벨이 있느냐. 라벨이 없으면 눈이 걸릴 데가 없어 전부 읽어야 한다.
//
// [하는 일] 내용은 한 글자도 바꾸지 않는다. 없는 문장을 지어내지도, 불릿을 합치지도 않는다.
//   1) 줄 중간에 뭉친 불릿을 제 줄로 내린다
//   2) 리드 문장이 없으면 첫 불릿을 리드로 올린다 (문장이 이미 거기 있다)
//   3) 라벨 없는 불릿의 머리 주제어를 굵게 만든다 (보수적으로 — 애매하면 그냥 둔다)
//   4) 블록으로 재조립해 빈 줄을 정리한다
// 2~3은 이미 형식을 지킨 답변에는 아무 일도 하지 않는다.

const HEAD = '(?:💡\\s*)?\\*\\*[^*\\n]{1,40}\\*\\*\\s*[:：]';

let t = String($json.text || '').trim();

// 0) 출처 표기를 걷어낸다. 형식 규칙에 "출처나 파일명은 쓰지 말 것"이라고 적혀 있지만
//    프롬프트가 근거를 [출처: 경로] 헤더와 함께 싣기 때문에 모델이 종종 그대로 베낀다
//    (실측: 벤치 답변 55건 중 11건에 위키링크가 샜고, 문장 끝 (출처: …) 형태도 관측됐다).
//    출처는 Reply to Discord 가 실제로 쓴 노트만 골라 따로 붙이므로 본문에 있으면 중복이자 노이즈다.
//    근거 규칙과 같은 이유로, 프롬프트에 부탁하는 대신 여기서 지운다.
t = t
  .replace(/[（(]\s*출처\s*[:：][^)）]*[)）]/g, '')   // 문장 끝 (출처: study/x.md)
  .replace(/\[\s*출처\s*[:：][^\]]*\]/g, '')        // 프롬프트 헤더를 그대로 베낀 [출처: …]
  .replace(/\[\[([^\]|]*\|)?([^\]]*)\]\]/g, '$2') // 옵시디언 위키링크 — 표시 텍스트만 남긴다
  .replace(/(?:^|\n)\s*출처\s*[:：][^\n]*/g, '')     // "출처: …" 로 시작하는 줄 통째
  .replace(/(\S)[ \t]{2,}/g, '$1 ')                  // 지운 자리에 생긴 연속 공백
                                                    // (줄 앞 들여쓰기는 건드리지 않는다 — 중첩 불릿이 있다)
  .replace(/\s+([.,!?)\]])/g, '$1')                  // 구두점 앞에 남은 공백
  .replace(/[ \t]+$/gm, '');

// 1) 앞에 개행 없이 붙어 있는 불릿을 제 줄로 내린다 (개행 뭉침 사고 복구)
// 앞이 공백이 아닐 때만 자른다. [^\\n] 은 공백도 먹어서 들여쓴 중첩 불릿의
// 들여쓰기까지 삼켰다 (2026-09-14 발견 — 주석은 보존한다고 적혀 있는데 코드가 반대였다).
t = t.replace(new RegExp('(\\S)[ \\t]+[-•*][ \\t]+(?=' + HEAD + ')', 'g'), '$1\n- ');
// 불릿 기호 통일 — Discord는 •를 목록으로 렌더하지 않는다
t = t.replace(/^[ \t]*[•*][ \t]+/gm, '- ');

// 빈 줄을 버리지 않는다. 2026-09-15 이전에는 전부 버리고 블록 사이에만 다시 넣었는데,
// 그러면 비교형(리드 문장 + **A** / **B** 대조 줄)이나 산문 단락의 의도한 빈 줄이 먹혀
// 문단이 통째로 붙어 나온다. 이제는 모델이 넣은 빈 줄을 존중하고 과한 것만 줄인다.
let lines = t.split('\n').map((l) => l.replace(/[ \t]+$/, ''));
while (lines.length && lines[0] === '') lines.shift();
while (lines.length && lines[lines.length - 1] === '') lines.pop();
// 들여쓴 중첩 불릿도 목록으로 본다. 안 그러면 블록 재조립이 중첩 항목을 목록에서
// 떼어내 앞뒤에 빈 줄을 넣어버린다.
const isBullet = (l) => /^\s*-\s/.test(l);

// 2) 첫 줄이 불릿이면 리드 문장이 없다는 뜻 — 첫 불릿을 끌어올린다.
//    불릿이 3개 미만이면 건드리지 않는다(짧은 답변에서 목록이 사라지면 더 이상하다).
const firstIdx = lines.findIndex((l) => l !== '');
if (firstIdx !== -1 && isBullet(lines[firstIdx]) && lines.filter(isBullet).length >= 3) {
  const lead = lines[firstIdx]
    .replace(/^-\s+/, '')
    .replace(/^(?:💡\s*)?\*\*([^*\n]+)\*\*\s*[:：]\s*/, '$1: ') // 리드는 굵게 쓰지 않는 게 규칙이다
    .replace(/\*\*/g, '');
  lines = [lead].concat(lines.slice(firstIdx + 1));
}

// 3) 라벨 없는 불릿의 머리 주제어를 굵게.
//    "임베딩 모델은 텍스트를 …" → "**임베딩 모델**: 텍스트를 …"
//    보수적으로 간다 — 조사 은/는 앞이 2~14자이고, 문장부호가 없고, 어미(…다)로 끝나지
//    않을 때만. "점수비가 크다는 건 …" 같은 관형절을 주제어로 오인하지 않기 위해서다.
//    조사 이/가는 제외한다("리랭커가 …"는 주제어가 아닌 경우가 많다).
// 수량자를 게으르게 둔다. 탐욕적이면 문장 뒤쪽 조사를 잡아
//   "M2는 실험으로 같은 결론에…" → 머리를 "M2는 실험으로 같"으로 오려낸다.
const LABEL = /^-\s+([^\s*:：.,!?()[\]]{1,6}?(?:\s[^\s*:：.,!?()[\]]{1,10}?){0,2}?)(은|는)\s+(.+)$/;
lines = lines.map((l) => {
  if (!isBullet(l) || l.includes('**')) return l;      // 이미 라벨이 있으면 그대로
  const m = l.match(LABEL);
  if (!m) return l;
  const head = m[1];
  if (head.length < 2 || head.length > 14) return l;
  if (/다$/.test(head)) return l;                      // 관형절("…크다는 건")을 주제어로 오인하지 않는다
  return '- **' + head + '**: ' + m[3];
});

// 4) 빈 줄 정규화 — 모델이 넣은 것은 살리고, 과한 것만 줄이고, 목록 앞은 한 줄 띄운다.
//    (블록을 통째로 재조립하던 방식은 대조·산문 형식의 문단을 뭉개서 버렸다.)
const out = [];
for (let k = 0; k < lines.length; k++) {
  const line = lines[k];
  if (line === '') {
    if (out.length && out[out.length - 1] !== '') out.push('');  // 연속 빈 줄은 하나로
    continue;
  }
  // 목록이 시작되는데 앞이 본문이면 한 줄 띄운다
  const prev = out.length ? out[out.length - 1] : null;
  if (prev && prev !== '' && isBullet(line) && !isBullet(prev)) out.push('');
  out.push(line);
}
t = out.join('\n');

return [{ json: { ...$json, text: t } }];

// ── 맥락 재작성 ──────────────────────────────────────────────────────────────
// 직전 턴(세션 로드)이 살아 있고 이번 질문이 "혼자서는 못 읽히는" 질문일 때만
// 검색용 질문을 다시 쓴다. 그 외에는 아무것도 하지 않는다 — question 이 한 글자도
// 안 바뀌므로 임베딩·검색·게이트·선별·프롬프트가 전부 지금과 바이트 단위로 같다.
//
// [왜 검색용만 바꾸나]
// 재작성은 추측이다. 추측을 답변 프롬프트의 "질문" 자리에 넣으면 잘못 추측했을 때
// 사용자가 하지도 않은 질문에 답하게 된다. 검색은 틀려도 게이트가 막아주지만
// 답변은 막아줄 게 없다. 그래서 프롬프트에는 원문을 넣고, 직전 턴은 따로
// [대화 맥락] 블록으로 붙여 모델이 스스로 지시어를 풀게 한다.

const TTL_S      = 600;   // 세션 수명(초). Discord 실측 근거는 보고서 참조.
const MAX_TOPIC  = 3;     // 직전 주제어를 몇 개까지 끌어올지
const CONTENT_MAX = 1;    // 지시어가 있을 때, 내용어가 이 개수 이하면 후속으로 본다

// ── 토크나이저 — `근거 판정` 노드의 것을 그대로 가져왔다 (같은 파일을 두 번 쓰지 못해 복제) ──
const TAILS = ["이랑","에서","으로","에게","한테","부터","까지","보다","처럼","마다","대로",
  "밖에","조차","라도","이나","하고","에는","과는","와는","이란","라는","이라",
  "은지","는지","한지","인지","이야","예요","이에","해줘","해야","하는",
  "랑","와","과","은","는","이","가","을","를","의","에","도","만","로","다",
  "요","야","지","고","서","며","면","나","까","죠","네","군","데","해","라","게","걸","건"];
const STOP = new Set(("뭐 뭘 뭔 뭐야 뭐가 뭔지 무슨 무엇 어떻 어떻게 어떤 어디 언제 누가 얼마 얼마나 왜 " +
  "알려 알려줘 설명 설명해 정리 가르쳐 말해 얘기 이야기 " +
  "차이 다른 다르 달라 비교 각각 중에 중 골라 골라야 선택 고르 골랐 " +
  "써 쓰 쓸 쓴 쓰나 쓰면 쓰는 써야 썼어 썼 사용 적용 " +
  "필요 이유 방법 관계 정확 자꾸 헷갈 헷갈리 그냥 그리고 좀 진짜 혹시 대해 대한 관련 " +
  "에서 으로 에게 한테 부터 까지 보다 처럼 이랑 하고 " +
  "것 거 게 건 걸 수 때 때문 경우 정도 부분 내용 문제 이거 그거 저거 이런 그런 " +
  "있어 없어 되나 되는 된다 맞아 맞나 인가 일까 할까 하면 한다 이란 라면").split(/\s+/));

// ── 지시어 — 두 갈래를 구분한다 ─────────────────────────────────────────────
// REF(지시대명사/지시관형사)  "그건 왜 비싸?"  → **가리키는 대상이 앞 차례에 있다**
// CONN(담화 접속부사)        "그럼 임베딩은?" → 앞 차례를 잇기만 할 뿐 가리키지 않는다
// 둘을 섞으면 "그럼 임베딩은 뭐야?"(주제 전환)에 직전 주제를 덧붙여 검색을 망친다.
// 실제로 그 질문은 실행 2121 에 있다 — 임베딩만으로 충분히 검색되는 질문이다.
// 그래서 **재작성 스위치는 REF 만** 켠다. CONN 은 내용어가 0일 때만(= 검색할 말이
// 아예 없을 때만) 의미를 갖는다.
//
// 원형(raw run)에 대고 맞춘다. 꼬리를 떼고 집합에 넣는 방식은 "저는"(=나는) → "저",
// "이야기" → "이" 처럼 지시어가 아닌 말을 지시어로 만든다.
// 맨 "그"/"이"/"저" 는 조사 없이 홀로 선 관형사일 때만 인정한다("그 리랭킹" ○, "저는" ✗).
const PART = "(?:[은는이가을를도만의랑와과]|에|에서|로|으로|라도|까지|부터)*";
// **지시대명사만** 방아쇠로 삼는다. 지시관형사(그런/이런/저런)와 맨 관형사(그/이/저)는 뺐다 —
// 그것들은 언제나 뒤따르는 명사를 꾸미고, 그 명사가 곧 내용어라 질문이 혼자 못 서는 경우가
// 드물다. 넣어 봤더니 "그 얘기 말고 데드락 조건 알려줘" 가 후속으로 오판됐다
// (꼬리 제거기가 "조건"→"조" 로 깎아 내용어를 1개로 세는 바람에 문턱을 넘었다).
// 빼도 잃는 게 없다 — "그런 거 언제 써?" 같은 건 내용어가 0이라 규칙 ①이 이미 잡는다.
const REF  = new RegExp("^(?:그것|그거|그건|그걸|그게|이것|이거|이건|이걸|이게|" +
  "저것|저거|저건|저걸|저게|그놈|그분|그때|그쪽|걔|얘|쟤|얘네|걔네|" +
  "거기|저기|여기|아까|방금)" + PART + "$");
const CONN = /^(?:그럼|그러면|그래서|그런데|근데|그리고|그래|그러니까)$/;
// 재작성 **방아쇠는 아니지만** 재작성할 때는 걷어내는 말. 지시관형사와 맨 관형사가 여기 온다.
// "그런 거 언제 써?" → 규칙 ①(내용어 0)로 후속이 되고, 재작성문에서 "그런"은 빠진다.
const FILL = /^(?:그런|이런|저런|그|이|저)$/;

const RUN = /[가-힣]+|[A-Za-z0-9]+(?:[-+.][A-Za-z0-9]+)*/g;

function stems(q) {
  const out = [];
  for (const run of String(q || "").match(RUN) || []) {
    let t = run, latin = /^[A-Za-z0-9]/.test(run);
    if (latin) t = t.toLowerCase();
    else for (const tl of TAILS) {
      if (t.length > tl.length && t.endsWith(tl)) { t = t.slice(0, -tl.length); break; }
    }
    out.push({ run, t, latin });
  }
  return out;
}

// 내용어 = 지시어도 골격어도 아닌 2자 이상 어간 (중복 제거, 등장 순서 유지).
// 영문은 원형을 그대로 돌려준다 — 검색 질문에 다시 넣을 때 "JWT" 가 "jwt" 로 뭉개지지 않게.
function contentWords(q) {
  const out = [], seen = new Set();
  for (const { run, t, latin } of stems(q)) {
    if (isRef(run) || isConn(run)) continue;
    if (t.length < 2 || STOP.has(t)) continue;
    if (!seen.has(t)) { seen.add(t); out.push(latin ? run : t); }
  }
  return out;
}
const isRef  = (run) => REF.test(run);
const isConn = (run) => CONN.test(run);
function hasRef(q)  { return (stems(q) || []).some(({ run }) => isRef(run)); }
function hasConn(q) { return (stems(q) || []).some(({ run }) => isConn(run)); }

// 지시어 낱말을 통째로 걷어낸 나머지 — 재작성의 뼈대가 된다
function stripDeictic(q) {
  let s = String(q || "");
  for (const { run } of stems(q)) {
    if (isRef(run) || isConn(run) || FILL.test(run)) s = s.split(run).join(" ");
  }
  return s.replace(/\s+/g, " ").replace(/^[\s,.]+/, "").trim();
}

// ── 본체 ────────────────────────────────────────────────────────────────────
const q0 = $('질문 정리').first().json;
const question = String(q0.question || "");

let sess = {};
try { sess = $input.first().json || {}; } catch (e) { sess = {}; }

const prevQ     = String(sess.prev_question || "");
const prevLead  = String(sess.prev_answer || "");
const prevTopic = String(sess.prev_topic || "");
const ageS      = (sess.age_s === null || sess.age_s === undefined) ? null : Number(sess.age_s);
const alive     = !!prevQ && ageS !== null && isFinite(ageS) && ageS >= 0 && ageS < TTL_S;

const words  = contentWords(question);
const ref    = hasRef(question);
const conn   = hasConn(question);
// 후속 판정 — 둘 중 하나
//   ① 내용어가 아예 없다 → 이 질문만으로는 검색어를 만들 수 없다(접속부사만 있어도 해당)
//   ② 지시대명사가 있고 내용어가 CONTENT_MAX 이하 → 지시어가 빠진 자리를 앞 차례가 채운다
const needy  = words.length === 0 || (ref && words.length <= CONTENT_MAX);
const isFollowUp = alive && needy;

// 재작성문 만들기. 1차 판정과 재검색(아래)이 **같은 함수**를 쓴다 — 두 벌로 갈라지면
// "게이트가 막은 질문을 무엇으로 다시 물었나" 가 1차 규칙과 달라진다.
function rewrite() {
  // 직전 주제어: 직전 질문에서 뽑되, 직전 질문도 후속이었다면 이월된 topic 을 쓴다
  let topic = contentWords(prevQ).slice(0, MAX_TOPIC).join(" ");
  if (!topic) topic = prevTopic;
  const rest = stripDeictic(question);
  const q = (topic + " " + rest).replace(/\s+/g, " ")
              .replace(/\s+([?!.,])/g, "$1").trim() || question;
  const block = "[대화 맥락 — 바로 앞 차례]\n" +
                "이전 질문: " + prevQ + "\n" +
                (prevLead ? "이전 답변 요지: " + prevLead + "\n" : "") +
                "위 맥락을 참고해 아래 질문의 지시어(그것/그건/그럼 …)가 무엇을 가리키는지 판단하세요.\n\n";
  return { q: q, block: block };
}

let searchQuestion = question;
let contextBlock   = "";
if (isFollowUp) {
  const r = rewrite();
  searchQuestion = r.q;
  contextBlock   = r.block;
}

// ── 재검색용 예비 재작성 — 여기서는 **쓰지 않는다** ─────────────────────────
// 아래 두 값은 이번 차례의 검색에 한 글자도 영향을 주지 않는다. ② 가 맨몸 질문으로
// 먼저 검색하고, **게이트가 막았을 때만** 이 값으로 한 번 더 검색한다.
//
// [왜 CONN 을 여기서는 방아쇠로 쓰나]
// 1차에서 CONN(그럼/그러면/그래서/근데)을 방아쇠로 쓰면 주제 전환 질문이 오염된다 —
// "그럼 임베딩은 뭐야?"(실행 2121)가 "리랭킹 임베딩은 뭐야?" 로 재작성된다.
// 그런데 그 질문은 게이트를 **넉넉히** 통과한다(실측 best2mean 0.3572 < NEAR 0.420).
// 통과하면 재검색은 아예 돌지 않으므로 오염될 자리가 없다. 반대로 "그러면 많이 비쌈?"
// (실행 2636)은 막힌다(best2mean 0.4937, lexHit 0.50). 막힌 질문에만 맥락을 붙이는 것이
// 이 설계다 — **판정을 규칙이 아니라 이미 있는 게이트에 맡긴다.**
//
// [문턱을 1차보다 한 칸 넉넉히 두는 이유]
// 1차(CONTENT_MAX=1)보다 느슨한 2로 둔다. 게이트가 이미 한 번 걸러 준 뒤라 오판의
// 대가가 작고, "그러면 리랭크 많이 비쌈?" 처럼 내용어 2개짜리 후속이 실제로 있다.
// 그래도 REF/CONN 이 **없는** 질문은 절대 대상이 아니다 — "러스트의 소유권 알려줘" 가
// 막혔다고 앞 차례 주제를 붙여 되살리면 사용자가 하지도 않은 질문에 답하게 된다.
const RETRY_CONTENT_MAX = 2;
// 1차에서 이미 재작성했다면(isFollowUp) 재검색해 봐야 같은 질문이라 뜻이 없다.
const retryNeedy = alive && !isFollowUp && (ref || conn) && words.length <= RETRY_CONTENT_MAX;
let ctxRetryQuestion = "";
let ctxRetryContext  = "";
if (retryNeedy) {
  const r = rewrite();
  if (r.q !== searchQuestion) { ctxRetryQuestion = r.q; ctxRetryContext = r.block; }
}

// 이월 topic — 이번 턴이 무엇에 관한 것이었는지. 후속이면 직전 것을 물려받는다.
const carry = contentWords(searchQuestion).slice(0, MAX_TOPIC).join(" ") || prevTopic;

return [{
  json: {
    ...q0,
    question: searchQuestion,   // ← 하류(검색·게이트·선별)가 읽는 질문
    rawQuestion: question,      // ← 사용자가 실제로 친 말. 답변 프롬프트가 읽는다
    contextBlock,               // ← 후속일 때만 비어 있지 않다
    ctxFollowUp: isFollowUp,
    ctxTopic: carry,
    ctxAgeS: ageS,
    ctxPrevQuestion: prevQ,
    ctxRef: ref,
    ctxConn: conn,
    ctxContentWords: words.length,
    // ↓ 재검색 전용. 이번 검색에는 안 쓰인다 — ② `재검색 판정` 이 게이트 결과를 보고 쓴다.
    ctxCanRetry: !!ctxRetryQuestion,
    ctxRetryQuestion,
    ctxRetryContext,
  },
}];

// ── 세션 기록 ────────────────────────────────────────────────────────────────
// 이번 차례를 세션 표에 남길 모양으로 만든다. Reply 뒤에 붙어 있으므로 여기서 무엇을 하든
// 사용자가 체감하는 응답 시간에는 영향이 없다.
//
// [왜 실패한 차례도 남기나]
// 남기지 않으면 "근거 없음"으로 끝난 다음의 "그건 …" 이 **두 차례 전** 주제를 가리키게 된다.
// 사용자 입장에서는 방금 못 찾겠다고 한 것을 되묻는 건데 엉뚱한 옛 주제가 붙는 셈이다.
// 실패도 기록해 두면 그 되묻기는 같은 주제로 다시 실패한다 — 정직하고 예측 가능하다.
const c = $('맥락 재작성').first().json;
const q = $('질문 정리').first().json;

let lead = '';
try {
  const t = String($('답변 정리').first().json.text || '').trim();
  lead = (t.split('\n').find((l) => l.trim()) || '').replace(/\*\*/g, '').trim().slice(0, 200);
} catch (e) { lead = ''; }        // 근거 없음 분기 — text 가 '' 라 리드도 빈다

// 코어가 서브워크플로로 나가면서 $('노트 선별') 을 더 이상 볼 수 없다. 대신 코어의 출력을 읽는다.
// 차단된 차례에 '없음' 이 아니라 빈 문자열을 넣는 것은 예전 동작 그대로다 —
// 예전에는 `노트 선별` 이 아예 안 돌아 catch 로 빠졌다.
let sources = '';
try {
  const r = $('RAG 코어').first().json;
  sources = r.grounded ? String(r.sourcesLine || '') : '';
} catch (e) { sources = ''; }

return [{
  json: {
    session_key: [q.guildId, q.channelId, q.authorId].join(':'),
    question: c.rawQuestion || c.question || '',
    answer_lead: lead,
    topic: c.ctxTopic || '',
    sources: sources,
  },
}];

// ── 출처 링크 ────────────────────────────────────────────────────────────────
// 출처 파일명을 옵시디언 URI 로 바꿔 Reply 가 실을 문자열(replyContent)까지 만든다.
// 본문(text)은 한 글자도 건드리지 않는다. 본문 손질은 `답변 정리` 의 일이고,
// ④ 답변 품질 평가가 그 노드의 jsCode 를 **바이트 그대로 복제**해 쓰고 있어서
// 거기를 고치면 ④ 가 조용히 배포본과 어긋난다. 그래서 새 노드로 왔다.
//
// ── 볼트 이름을 왜 상수로 박았나 ─────────────────────────────────────────────
// 유도할 방법이 없다. ① 볼트 증분 색인의 `Read Vault Files` 가 아는 것은
// 컨테이너 경로 `/home/node/vault/**/*.md` 뿐이고, 그게 호스트의 어느 폴더인지는
// docker-compose 의 bind mount 에만 있다:
//     <VAULT_PATH>  →  /home/node/vault   (ro)
// 어떤 워크플로도 이 사실을 모르므로 ① 에서 끌어올 수가 없다. 그래서 **여기 한 곳**에만 둔다.
// 볼트 폴더 이름을 바꾸거나 마운트를 옮기면 아래 두 줄만 고치면 된다.
//   확인 방법:  docker inspect n8n-n8n-1 --format '{{json .Mounts}}'
//              cat ~/Library/Application\ Support/obsidian/obsidian.json
const VAULT  = 'LLM Wiki';   // .obsidian 폴더가 들어 있는 볼트 루트의 이름
const PREFIX = 'wiki/';      // 색인 경로(study/x.md)를 볼트 기준 경로로 만드는 접두사
                             // (볼트 루트가 아니라 그 아래 wiki/ 를 마운트해 두었다)

// ── Discord 가 이걸 링크로 그려주는지는 확인하지 못했다 ──────────────────────
// 알아낸 것: Discord 는 **봇 메시지 본문**에서 `[글자](url)` 마스크 링크를 그린다.
// 모르는 것: `obsidian://` 같은 커스텀 스킴을 마스크 링크 URL 로 받아주는지.
//   (Discord 는 보통 http/https 만 링크로 인정한다. 거부하면 마스크 문법이
//    글자 그대로 남는데, 그래도 URI 전문이 본문에 남아 복사는 된다.)
// 실제 채널로 한 번 보내 보고 안 되면 LINK_STYLE 을 'plain' 으로 내리면 된다.
//   'masked' — [study/hnsw](obsidian://…)      클릭되면 가장 깔끔하다
//   'plain'  — study/hnsw — obsidian://…       절대 안 깨진다. 클릭은 안 된다
//   'off'    — study/hnsw.md, …                패치 전과 같다 (되돌리기용)
const LINK_STYLE = 'masked';
// 2026-09-15 실측: Discord 는 마스크 링크 URL 로 http(s) 만 받는다.
//   obsidian:// 는 본문에서도 임베드에서도 글자 그대로 남았다(테스트 메시지로 확인).
//   그래서 워크플로 ⑥ `노트 열기 다리`(webhook/open)가 http 로 받아 302 로
//   obsidian:// 에 넘긴다. 링크는 이 기계에서만 열린다 — 개인 볼트라 그게 맞다.

const LIMIT = 1990;

// encodeURIComponent 는 `/` 를 %2F 로 눕힌다(옵시디언은 둘 다 받지만 %2F 가 무난하다).
// 다만 ( ) ' ! * ~ 는 건드리지 않는데, 괄호는 마스크 링크의 괄호와 부딪힌다.
// 지금 볼트에는 공백·한글·괄호가 든 노트가 없지만(101개 전수 확인) 노트는 늘어난다.
const enc = (s) => encodeURIComponent(String(s))
  .replace(/[()]/g, (c) => (c === '(' ? '%28' : '%29'));

const V = enc(VAULT);
const BRIDGE = 'http://localhost:5678/webhook/open';
const uri = (src) => BRIDGE + '?f=' + enc(src);
const label = (p) => String(p).replace(/\.md$/i, '');

// 출처 목록. `노트 선별` 이 실제로 쓴 노트만 담은 배열(pickedNotes)이 원본이고,
// sourcesLine 은 그걸 ', ' 로 이어 붙인 표시용 문자열이다. 배열이 있으면 배열을 쓴다 —
// 파일명에 쉼표가 들어가도 쪼개지지 않는다.
let notes = Array.isArray($json.pickedNotes) ? $json.pickedNotes.filter(Boolean).map(String) : [];
if (!notes.length) {
  // 옛 실행이나 예상 못 한 모양 대비. '없음' 은 출처가 아니라 자리 표시다.
  const line = String($json.sourcesLine || '').trim();
  if (line && line !== '없음') notes = line.split(',').map((s) => s.trim()).filter(Boolean);
}

function render(style) {
  if (!notes.length) return String($json.sourcesLine || '없음');
  if (style === 'off')    return notes.map(label).join(', ');
  if (style === 'plain')  return notes.map((p) => label(p) + ' — ' + uri(p)).join('\n');
  return notes.map((p) => '[' + label(p) + '](' + uri(p) + ')').join(' · ');
}

const sourcesRendered = render(LINK_STYLE);

// ── 최종 본문 ───────────────────────────────────────────────────────────────
// 갈래를 가르는 식은 패치 전 `Reply to Discord` 의 content 식 그대로다:
//   근거 있음 → 본문 + 출처 줄 / 근거 없음 → noGroundMessage (출처 줄 없음)
const body = String($json.text || '');
let replyContent;
if (body) {
  const head = body.trim() + '\n\n📄 출처: ';
  replyContent = head + sourcesRendered;
  if (replyContent.length > LIMIT) replyContent = head + render('off');       // 링크를 뗀다
  if (replyContent.length > LIMIT) replyContent = replyContent.slice(0, LIMIT - 1) + '…';
} else {
  replyContent = String($json.noGroundMessage || '');
  if (replyContent.length > LIMIT) replyContent = replyContent.slice(0, LIMIT - 1) + '…';
}


// ── 보낼 채널 결정 ─────────────────────────────────────────────────────────
// 2026-09-15: URL 표현식에서 `$('스레드 열기').first().json.id || ...` 로 풀었더니
// Discord 가 405 를 돌려줬다(빈 채널 id 로 /channels//messages 가 된 것으로 보인다).
// 노드 간 표현식 대신 여기서 확정해 문자열 하나로 넘긴다 — 실패하면 여기서 드러난다.
let __chan = '';
try { const t = $('스레드 열기').first().json; if (t && t.id) __chan = String(t.id); } catch (e) {}
if (!__chan) { try { __chan = String($('Discord Trigger').first().json.channelId || ''); } catch (e) {} }




const __out = ([{ json: { ...$json, sourcesRendered, replyContent, replyLinkStyle: LINK_STYLE } }]);
__out[0].json.targetChannelId = __chan;
return __out;

// ── 거절 기록 ────────────────────────────────────────────────────────────────
// 답이 나가지 못한 질문을 한 행으로 만든다. 게이트가 막은 것 + 모델이 스스로 거절한 것.
// 공부 볼트에서 그 목록은 곧 "다음에 쓸 노트" 목록이다. 거절이 아니면 빈 배열을 돌려
// 뒤의 Postgres 노드를 아예 돌리지 않는다.
//
// [왜 ② 에만 두고 ⓪ 코어에는 안 두나]
// 코어에 넣으면 ④ 평가 실행이 통째로 이 표에 들어온다. ④ 의 음성 대조군은 **막히라고
// 만든 질문**이고 골든 문항은 매주 같은 것이 반복된다. 둘 다 기록될수록 "사람이 실제로
// 물었는데 답을 못 받은 것" 이라는 신호를 덮는다. ②T 같은 실험 워크플로도 같은 이유로
// 제외된다 — 코어가 아니라 ② 에만 있으면 자동으로 그렇게 된다.
//
