const RUN = /[가-힣]+|[A-Za-z0-9]+(?:[-+.][A-Za-z0-9]+)*/g;

// ── 반복 집계 키 ─────────────────────────────────────────────────────────────
// 내용어 어간만 남기고 **정렬해서** 잇는다. 정렬이 핵심이다 —
//   "리랭킹이 뭐야?" / "리랭킹 좀 알려줘" / "리랭커는 언제 써?"  → 전부 "리랭"
//   "카프카 리밸런싱 왜 나?" / "리밸런싱이랑 카프카 관계"        → 둘 다 "리밸런싱 카프카"
// 조사·어미·질문 골격어("뭐야/알려줘/차이")는 STOP 과 TAILS 가 걷어낸다.
// 어순까지 지우는 게 과한가 — 이 표의 용도는 "어떤 노트가 없는가" 지 "무엇을 물었는가"
// 가 아니다. 같은 빈자리를 가리키는 질문은 묶여야 목록이 짧아지고 행동이 나온다.
// 원문(raw_question)은 그대로 남으니 묶임이 이상하면 언제든 눈으로 되짚을 수 있다.
function normKey(q) {
  const out = [], seen = new Set();
  for (const run of String(q || "").match(RUN) || []) {
    let t = run;
    if (/^[A-Za-z0-9]/.test(run)) t = t.toLowerCase();
    else for (const tl of TAILS) {
      if (t.length > tl.length && t.endsWith(tl)) { t = t.slice(0, -tl.length); break; }
    }
    if (t.length < 2 || STOP.has(t)) continue;
    if (!seen.has(t)) { seen.add(t); out.push(t); }
  }
  // 내용어가 하나도 없으면(=골격어뿐인 질문) 정규화 대신 원문을 눌러 쓴다.
  // 묶이지 않을 뿐 잃는 건 없다.
  if (!out.length) return String(q || "").toLowerCase().replace(/\s+/g, " ").trim();
  return out.sort().join(" ");
}

// ── 본체 ────────────────────────────────────────────────────────────────────
// 상류가 안 돌았으면(오류로 여기까지 흘러온 경우) 조용히 아무것도 안 남긴다.
// 기록은 답변보다 덜 중요하다 — 여기서 throw 하면 실행이 빨개진다.
let r, q, c;
try {
  // 재검색(`결과 고르기`)이 돌았으면 최종 결과는 그쪽이다. 안 돌았으면 그 노드가 아예
  // 실행되지 않아 $() 가 던진다 — 그때는 패치 전과 똑같이 `RAG 코어` 를 읽는다.
  try { r = $('결과 고르기').first().json; } catch (e2) { r = null; }
  if (!r) r = $('RAG 코어').first().json;
  q = $('질문 정리').first().json;
  c = $('맥락 재작성').first().json;
} catch (e) { return []; }
if (!r) return [];

// 모델 자체 거절 판정 — ④ `Record` 의 것과 **바이트 단위로 같아야 한다**.
// 어긋나면 ④ 의 "근거 도달 실패" 집계와 이 표가 서로 다른 말을 하게 된다.
// 판정 대상도 ④ 와 같게 코어가 돌려준 원문(r.text)으로 한다 — `답변 정리` 를 거친
// 문자열이 아니다.
const ans = String(r.text || '');
const selfRefused = /찾지\s*못했|찾을\s*수\s*없|관련\s*내용이?\s*없|노트에\s*(?:관련|해당)[^.]*없|비교할\s*수\s*없|설명이?\s*없/.test(ans)
  && ans.length < 300;

const kind = r.grounded === false ? 'gate' : (selfRefused ? 'self' : null);
if (!kind) return [];                 // 정상 답변 — 아무것도 남기지 않는다

// 답변 리드(자체 거절일 때 모델이 뭐라고 했는지). `세션 기록` 과 같은 방식으로 뽑는다.
let lead = '';
try {
  const t = String($('답변 정리').first().json.text || '').trim();
  lead = (t.split('\n').find((l) => l.trim()) || '').replace(/\*\*/g, '').trim().slice(0, 200);
} catch (e) { lead = ''; }

// 정규화는 **검색에 실제로 쓴 질문**으로 한다. 후속 질문("그건 왜 비싸?")의 원문은
// 내용어가 없어 혼자서는 묶이지 않지만, 재작성된 질문에는 앞 차례 주제어가 들어 있다.
// 단발 질문에서는 둘이 같은 문자열이라 차이가 없다.
const searchQ = String(r.question || c.question || '');
const rawQ = String(r.rawQuestion || c.rawQuestion || q.question || '');

// 사용자 식별자는 **해시로만** 남긴다. 실제 해싱은 뒤 Postgres 노드의
// sha256() 이 한다(Code 노드 샌드박스에 crypto 가 없다 — 실측 확인).
// 여기서는 소금을 붙인 평문을 넘길 뿐이고, 표에는 앞 16자 해시만 들어간다.
//
// [왜 해시인가] 이 표의 용도는 "무슨 노트를 써야 하나" 다. 누가 물었는지는 필요 없다.
// 다만 "한 사람이 세 번" 과 "세 사람이 한 번씩" 은 우선순위가 다르므로 **구별은**
// 할 수 있어야 한다. 해시가 딱 그만큼만 준다. authorName("sejxn") 은 아예 안 남긴다.
// 채널 ID 는 개인정보가 아니고 "어느 방에서 나온 질문인가" 가 쓸모 있어 원문으로 둔다.
const salted = 'rag-refusals:v1:' + String(q.authorId || '');

const n = (v) => (typeof v === 'number' && isFinite(v) ? v : null);

return [{
  json: {
    kind,
    raw_question: rawQ.slice(0, 2000),
    question: searchQ.slice(0, 2000),
    norm_key: normKey(searchQ).slice(0, 500),
    ctx_follow_up: !!c.ctxFollowUp,
    ctx_topic: String(c.ctxTopic || '').slice(0, 200),
    channel_id: String(q.channelId || ''),
    salted_author: salted,
    best: n(r.best),
    best2mean: n(r.best2mean),
    spread: n(r.spread),
    lex_hit: n(r.lexHit),
    lex_tokens: n(r.lexTokens),
    nearest: String(r.nearest || ''),
    gate_sources: String(r.gateSourcesLine || ''),
    // 자체 거절일 때만 의미가 있다 — 모델이 무엇을 읽고도 거절했는지가 곧 진단이다.
    picked_notes: kind === 'self' ? String(r.sourcesLine || '') : '',
    answer_lead: kind === 'self' ? lead : '',
  },
}];

// ── 스레드 세션 키 (선택 패치) ───────────────────────────────────────────────
// 세션 키를 `길드:채널:사용자` 에서 `길드:스레드:사용자` 로 바꾼다 — **쓰기 쪽만**.
//
// [왜 쓰기만 바꾸면 되나]
// 읽기(`세션 로드`)는 이미 스레드 단위다. 사용자가 스레드 안에서 후속 질문을 하면
// Discord Trigger 가 주는 channelId 가 그 **스레드의 id** 라서(bot.js: message.channelId)
// 키가 저절로 갈린다. 문제는 첫 턴뿐이다 — 첫 질문은 채널에서 오므로 채널 키로 저장되고,
// 스레드 안의 첫 후속 질문은 스레드 키로 찾다가 빈손으로 돌아온다.
// 그 한 칸을 메우려고 저장 키만 스레드로 옮긴다.
//
// [왜 `세션 기록` 을 고치지 않고 노드를 하나 더 두나]
// ④ 답변 품질 평가가 `세션 기록` 의 jsCode 를 바이트 그대로 복제해 쓴다. 거기를 고치면
// ④ 가 조용히 배포본과 어긋난다. 그래서 뒤에 덧붙여 키만 갈아끼운다.
//
// [남는 한계]
// 맥락 수명(TTL 600초)은 `맥락 재작성` 안에 있고 그 노드도 ④ 에 복제돼 있어 건드리지 않았다.
// 스레드 대화가 10분 넘게 끊기면 여전히 맥락이 끊긴다.
const t = $('스레드 열기').first().json;
const d = $('Discord Trigger').first().json;
const chan = (t && t.id) ? t.id : d.channelId;   // 스레드 생성 실패 → 채널 키 (패치 전과 같다)
// 이 세션 키가 스레드인가 — `받을까?` 가 멘션 없이 받을지 고를 때 쓴다.
//   스레드를 새로 만들었다        → 저장 키가 그 스레드다
//   50024 (이미 스레드 안이다)   → channelId 가 곧 스레드다
//   50001 (권한 없음) · 그 밖     → 채널이다
const code = (((t || {}).error || {}).cause || {}).message || JSON.stringify((t || {}).error || '');
const isThread = !!(t && t.id) || /50024/.test(String(code));
return [{ json: { ...$json, is_thread: isThread,
                  session_key: [d.guildId, chan, d.authorId].join(':') } }];

// ── 결과 고르기 ──────────────────────────────────────────────────────────────
// 맨몸 질문이 게이트에 막혀 **맥락을 붙여 한 번 더** 검색했다. 둘 중 하나를 고른다.
//   재검색이 통과했다 → 재검색 결과로 답한다
//   재검색도 막혔다   → **1차 결과**를 그대로 돌려준다
// 1차를 돌려주는 게 중요하다. 거절 문구(noGroundMessage)와 nearest 가 사용자가 실제로
// 친 질문에 대한 말이어야 하고, 그래야 `거절 기록` 도 패치 전과 같은 행을 남긴다.
const first = $('RAG 코어').first().json;
const again = $input.first().json;
const won   = !!again.grounded;
const win   = won ? again : first;
return [{
  json: {
    ...win,
    ctxRetried: true,            // 관측용 — 재검색이 돌았다
    ctxRetryWon: won,            // 관측용 — 그래서 살아났나
    ctxRetrySearch: String(again.question || ''),
  },
}];
